// 의견·첨부 둘 다 Y 가 아니면 opinion Column 을 colSpan 2 로 mergeCell
scwin.dlt_ondataload = function() {
	setTimeout(() => {
		const opinionColumnIndex = grd_doc.getColumnIndex('opinion');
		$.each(dlt_doc.getAllJSON(), function (index, item) {
			const atrzOponCttYn = dlt_doc.getCellData(index, "atrzOponCttYn");
			const ecazAtflYn = dlt_doc.getCellData(index, "ecazAtflYn");
			if (atrzOponCttYn === "Y" && ecazAtflYn === "Y") {
				dlt_doc.setCellData(index, "opinion", "/pmb/cm/images/contents/skj_opinion.png");
				dlt_doc.setCellData(index, "atfl", "/pmb/cm/images/contents/skj_attach.png");
			} else if (atrzOponCttYn === "Y" && ecazAtflYn !== "Y") {
				grd_doc.mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2});
				dlt_doc.setCellData(index, "opinion", "/pmb/cm/images/contents/skj_opinion.png");
			} else if (atrzOponCttYn !== "Y" && ecazAtflYn === "Y") {
				grd_doc.mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2});
				dlt_doc.setCellData(index, "opinion", "/pmb/cm/images/contents/skj_attach.png");
			} else {
				grd_doc.mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2});
				dlt_doc.setCellData(index, "opinion", "");
				dlt_doc.setCellData(index, "atfl", "");
			}
		});
	}, 0);
};

scwin.checkVal1 = function() {
	return document.getElementById('mf_grd_doc_cell_5_8').getAttribute('colspan') == 2;
};
